const LESSONS=[
 {id:'caesar',name:'Caesar 凯撒移位',stage:'入门',scope:'基础预备 · 2027 C 组未列',time:6,desc:'用字母表位移理解加密与解密，作为后续密码的热身。',idea:'每个字母按固定格数移动。解密时向反方向移回去；空格保持不变。',steps:['写出 A–Z，给每个字母标 0–25。','尝试把密文中的字母统一向左移 1、2、3 格。','读出有意义的英语短句，再检查每个字母。'],cipher:'PHHW DW QRRQ',answer:'MEET AT NOON',hints:['试着把 P 往前数三格。','P→M，H→E，所以移位是 +3。','完整答案：MEET AT NOON。'],why:'加密向右移 3：M→P、E→H。解密则向左移 3，得到 MEET AT NOON。',tool:'caesar'},
 {id:'aristocrat',name:'Aristocrat 保留词界替换',stage:'替换',scope:'2027 C 组',time:12,desc:'空格和标点还在；用单词形状、词频和字母对应表破译。',idea:'一个密文字母始终对应同一个明文字母。词间空格保留，所以短词和重复模式是入口。',steps:['先观察 1–3 字母词和重复字母。','猜一个短词，记录密文→明文的对应。','把猜测应用到全句；若产生矛盾，撤销它。'],cipher:'CENPGVPR ZNXRF CEBTERFF',answer:'PRACTICE MAKES PROGRESS',hints:['第一个词是 8 个字母，P?A?T?C?。','C→P、E→R、N→A；把这三组填进对应表。','答案是 PRACTICE MAKES PROGRESS。'],why:'本教学题使用固定的一对一替换（恰好是 ROT13），保留空格。比赛题的替换表通常不会如此整齐；破译方法仍是建立并检验对应。',tool:'mapping'},
 {id:'patristocrat',name:'Patristocrat 无词界替换',stage:'替换',scope:'2027 C 组',time:13,desc:'与 Aristocrat 相似，但原文空格被移除或重分组。',idea:'单字母替换不变，词界线索消失。先找常见字母组合，再在草稿中重新切分单词。',steps:['找重复的 2–3 字母片段。','根据可能的 THE、ING 等建立少量映射。','在还原字母后重新切分句子。'],cipher:'GURXRLVFCNGVRAPR',answer:'THE KEY IS PATIENCE',hints:['开头三个字母可试 THE。','G→T、U→H、R→E；继续看 XRL。','字母流是 THEKEYISPATIENCE。'],why:'无词界密文解出字母流 THEKEYISPATIENCE；为了阅读，重新分成 THE KEY IS PATIENCE。',tool:'mapping'},
 {id:'xenocrypt',name:'Xenocrypt 西语替换',stage:'替换',scope:'2027 C 组',time:14,desc:'把单字母替换应用到西班牙语；用冠词、介词和常见词形找入口。',idea:'Xenocrypt 常见的是西班牙语明文。不要拿英语词频硬套；先看 LA、EL、DE、ES 等短词。',steps:['识别可能的西语短词和词尾。','写下字母对应；注意无重音大写文本。','解出后用西语语法和含义复核。'],cipher:'YN PYNIR RF CENPGVPNE',answer:'LA CLAVE ES PRACTICAR',hints:['第一个词可试 LA。','YN→LA，RF→ES。','整句是 LA CLAVE ES PRACTICAR。'],why:'教学题沿用简单一对一替换，明文为“关键在于练习”。正式试题的词汇和替换会更复杂。',tool:'mapping'},
 {id:'baconian',name:'Baconian 培根密码',stage:'符号',scope:'2027 C 组',time:10,desc:'把两类外观符号读成 A/B，再每五个一组。',idea:'每个明文字母由五个 A/B 位组成。先分辨两类符号，再稳定地五位分组。',steps:['把两种外观统一记为 A 和 B。','每 5 位切开，查 Baconian 对照表。','把字母连起来检查是否成词。'],cipher:'AAABA  ABBBA  AAABB  AABAA',answer:'CODE',hints:['第一组 AAABA 对应 C。','第二组 ABBBA 对应 O。','四组依次是 C O D E。'],why:'这里使用 26 字母的教学版映射：A=AAAAA，B=AAAAB，C=AAABA。比赛可能把 A/B 隐藏在字体等外观差异里。',tool:'bacon'},
 {id:'morse',name:'Morse 与 Fractionated Morse',stage:'符号',scope:'2027 C 组：Fractionated Morse',time:16,desc:'先会点划码，再理解点、划、分隔符如何被切成三元组。',idea:'Fractionated Morse 把摩斯码串连同分隔符 x 每三个符号切开，再经一张字母表替换。这里先用按字母顺序的教学映射。',steps:['把密文字母查回三元组。','将三元组串接，x 视为字母分隔。','按摩斯码表读出明文。'],cipher:'KHOJU',answer:'CODE',hints:['按教学三元组表，K→-.-。','KHOJU → -.-.x---x-..x.x。','分隔后是 -.-. / --- / -.. / .，即 CODE。'],why:'标准摩斯码 C=-.-.、O=---、D=-..、E=.。本题三元组按 ...、..-、..x、.-. 等顺序映射 A–Z；正式题常有关键词字母表和更长密文。',tool:'morse'},
 {id:'porta',name:'Porta 波塔密码',stage:'多表',scope:'2027 C 组',time:14,desc:'使用两两成组的关键词行；同一个表可加密也可解密。',idea:'Porta 把关键词 A/B、C/D……Y/Z 配成 13 行。按关键词循环选行，再在该行找到密文字母。',steps:['把关键词循环写在密文上方。','把每个关键词字母归到它的双字母行。','用对应行逐字解密，再通读检查。'],cipher:'NYSE',key:'CODE',answer:'MEET',hints:['关键词 CODE，逐字配 C、O、D、E。','用 C/D 行，N 对应 M。','解密结果是 MEET。'],why:'Porta 是互逆的：同一行在 A–M 与 N–Z 两半之间配对。教学题 NYSE 配关键词 CODE 还原 MEET。',tool:'porta'},
 {id:'homophonic',name:'Homophonic 同音替换',stage:'替换进阶',scope:'2027 C 组 · 新增',time:15,desc:'同一个明文字母可能对应多个数字符号，单纯字母频率会被摊平。',idea:'一对多替换：高频字母可分到多个密文符号。寻找重复词形、提示片段和符号分布。',steps:['先把题目给出的已知映射写入表中。','观察哪些符号可能代表同一个高频字母。','逐个替换并检验整句，不要假设不同数字必是不同字母。'],cipher:'41 07 19 74',answer:'MEET',hints:['41 对应 M。','07 和 19 虽不同，但都对应 E。','74 对应 T，得到 MEET。'],why:'教学映射为 41→M、07→E、19→E、74→T。正式 2027 题会要求更多密码分析；此题专练“一字多码”概念。',tool:'homophonic'},
 {id:'nihilist',name:'Nihilist Substitution 虚无主义替换',stage:'坐标与数字',scope:'2027 C 组',time:17,desc:'先用 5×5 Polybius 方阵取坐标，再逐位加上关键词坐标。',idea:'先把字母变成 11–55 的行列坐标。加密时与循环关键词坐标相加；解密时逐项相减。',steps:['列出 5×5 方阵，I/J 共格。','把关键词 KEY 变为 25、15、54、25。','密文数字逐项减去关键词数字，再查回字母。'],cipher:'38 49 68 40',key:'KEY',answer:'CODE',hints:['38−25=13，对应 C。','49−15=34，对应 O。','后两项是 68−54=14、40−25=15。'],why:'教学方阵按 ABCDE / FGHIK / LMNOP / QRSTU / VWXYZ 排列。13=C、34=O、14=D、15=E。正式题可能使用关键词方阵。',tool:'polybius'},
 {id:'checkerboard',name:'Checkerboard 棋盘密码',stage:'坐标与数字',scope:'2027 C 组',time:18,desc:'用行列标签读双字母坐标；正式题还涉及方阵关键词与推断。',idea:'教学入门先读坐标：第一个字符决定行，第二个决定列。正式题可能隐藏行列关键词和方阵关键词。',steps:['写下行标签 C O D E S 与列标签 T R A I N。','按双字符一组，从行列交叉处取字母。','复核每组坐标与明文长度。'],cipher:'CA DI CI CN',answer:'CODE',hints:['CA 是 C 行、A 列，即第 1 行第 3 列。','DI 是 D 行、I 列，即第 3 行第 4 列。','四组依次 C、O、D、E。'],why:'教学方阵按字母顺序排布。2027 竞赛棋盘题的关键词和密码分析要求更高；这里仅练坐标读取。',tool:'checkerboard'},
 {id:'cryptarithm',name:'Cryptarithm 字母算式',stage:'综合',scope:'2027 C 组 · 十进制',time:18,desc:'每个字母代表唯一数字；用进位与首位非零约束推理。',idea:'同一字母永远是同一数字，不同字母不可共用数字，最高位不为 0。按列写进位。',steps:['从最左列判断 M=1。','逐列处理进位，检查每个字母的数字唯一。','用普通算式复核最终数字。'],cipher:'SEND + MORE = MONEY',answer:'9567+1085=10652',hints:['两个四位数相加成五位数，所以 M=1。','经典解中 O=0，S=9，E=5。','SEND=9567、MORE=1085、MONEY=10652。'],why:'9567 + 1085 = 10652，字母映射 S9 E5 N6 D7 M1 O0 R8 Y2；各字母使用不同数字。',tool:'cryptarithm'},
 {id:'columnar',name:'Complete Columnar 完全列换位',stage:'综合',scope:'2027 C 组',time:18,desc:'把文字按行写入矩形，再按关键词列顺序读出。',idea:'完全列换位在最后一行也填满方格。密文字母本身不变，位置改变；破译时先找列数和列顺序。',steps:['关键词 ZEBRA 有 5 列，10 个字母形成 2 行。','按关键词字母序 A、B、E、R、Z 安排列读取顺序。','把密文切成五段，每段 2 字母，放回原列。'],cipher:'ANEOENTOMT',key:'ZEBRA',answer:'MEET AT NOON',hints:['五段为 AN / EO / EN / TO / MT。','它们对应原来的第 5、3、2、4、1 列。','逐行读出 MEETATNOON。'],why:'原矩形为 M E E T A / T N O O N；按 ZEBRA 的字母顺序读列得到 AN EO EN TO MT。',tool:'columnar'}
];
const STAGES=[{name:'入门',description:'先用位移建立字母表直觉；这节是 C 组预备知识。',ids:['caesar']},{name:'替换',description:'从保留词界到无词界，再到西语与一字多码。',ids:['aristocrat','patristocrat','xenocrypt','homophonic']},{name:'符号',description:'训练二元符号、摩斯点划与三元组。',ids:['baconian','morse']},{name:'多表与坐标',description:'学关键词驱动的字母表和 5×5 方阵。',ids:['porta','nihilist','checkerboard']},{name:'综合',description:'把逻辑推理和列换位放进限时练习。',ids:['cryptarithm','columnar']}];
const MAIN=document.getElementById('main');
const STORAGE='codebusters-2027-progress-v1';
let progress=loadProgress();let view='home';let activeLesson='caesar';let hintCount={};let mock=null;let tick=null;
function loadProgress(){try{return JSON.parse(localStorage.getItem(STORAGE))||{done:{},attempts:0,bestMock:0}}catch{return{done:{},attempts:0,bestMock:0}}}
function saveProgress(){try{localStorage.setItem(STORAGE,JSON.stringify(progress))}catch{}}
function norm(x){return String(x||'').toUpperCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^A-Z0-9]/g,'')}
function findLesson(id){return LESSONS.find(x=>x.id===id)}
function countDone(){return Object.keys(progress.done).filter(x=>progress.done[x]).length}
function button(label,action,cls='secondary'){return `<button class="${cls}" data-action="${action}">${label}</button>`}
function navigate(next,id){view=next;if(id)activeLesson=id;location.hash=next==='lesson'?`lesson/${id}`:next;render();window.scrollTo(0,0);document.getElementById('sidebar').classList.remove('open');document.getElementById('menu-toggle').setAttribute('aria-expanded','false')}
function renderNav(){document.querySelectorAll('.nav-button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));document.getElementById('lesson-nav').innerHTML=LESSONS.map(l=>`<button class="lesson-link ${progress.done[l.id]?'done':''} ${view==='lesson'&&activeLesson===l.id?'active':''}" data-lesson="${l.id}"><span class="dot"></span><span>${l.name}</span></button>`).join('');document.getElementById('sidebar-progress').textContent=`${countDone()} / ${LESSONS.length} 已掌握`;document.getElementById('sidebar-progress-bar').style.width=`${countDone()/LESSONS.length*100}%`}
function render(){renderNav();syncLanguageLinks();MAIN.innerHTML=view==='home'?home():view==='lessons'?courses():view==='lesson'?lesson(findLesson(activeLesson)):view==='mock'?mockPage():resources();if(view==='lesson')activateTool(findLesson(activeLesson));if(view==='mock')renderMockTimer()}
function home(){const next=LESSONS.find(l=>!progress.done[l.id])||LESSONS[1];return `<div class="page-top"><div><h1>从零开始，读懂每一道密文。</h1><p>面向高中生的 Codebusters 中文学习路线，关键术语保留英文。每节课先看方法，再亲手解一道题。</p></div><button class="top-action" data-view="resources">核对竞赛范围 ↗</button></div><div class="summary"><div><h2>下一步：${next.name}</h2><p>${next.desc}</p></div><button class="primary" data-lesson="${next.id}">继续学习 →</button></div><div class="stats"><div class="stat"><strong>${countDone()} / ${LESSONS.length}</strong><span>已掌握课程</span></div><div class="stat"><strong>${progress.attempts||0}</strong><span>练习提交次数</span></div><div class="stat"><strong>${progress.bestMock||0} / 5</strong><span>模拟最佳成绩</span></div></div><div class="notice"><p><strong>2027 范围说明：</strong>Caesar 是入门预备知识；Morse 的竞赛题型是 Fractionated Morse。课程中的短题是原创教学简化题，不等同正式试题。正式范围以 <a href="https://www.soinc.org/rules-2027" target="_blank" rel="noopener">Division C 官方规则手册</a>及后续修订为准。</p></div><div class="section-head"><h2>分阶段路线</h2><p>建议按顺序学习，也可直接选择题型。</p></div><div class="stage-list">${STAGES.map(s=>`<section class="stage"><div><h3>${s.name}</h3><p>${s.description}</p></div><div class="stage-links">${s.ids.map(id=>{let l=findLesson(id);return `<button class="${progress.done[id]?'complete':''}" data-lesson="${id}">${progress.done[id]?'已完成 · ':''}${l.name}</button>`}).join('')}</div></section>`).join('')}</div>`}
function courses(){return `<div class="page-top"><div><h1>全部课程</h1><p>12 个专题，按解题技能组织。标注“2027 C 组”的题型依据下方规则来源整理。</p></div><button class="top-action" data-view="mock">进入定时模拟</button></div><div class="course-grid">${LESSONS.map(l=>`<article class="course"><div><span class="status ${progress.done[l.id]?'done':l.id==='caesar'?'foundation':'current'}">${progress.done[l.id]?'已掌握':l.scope}</span></div><h3>${l.name}</h3><p>${l.desc}</p><div class="course-footer"><span class="micro">约 ${l.time} 分钟 · ${l.stage}</span><button class="text-button" data-lesson="${l.id}">开始 →</button></div></article>`).join('')}</div>`}
function lesson(l){if(!l)return courses();const idx=LESSONS.indexOf(l);const next=LESSONS[idx+1];return `<div class="page-top"><div><h1>${l.name}</h1><p>${l.desc}</p></div><span class="status ${l.id==='caesar'?'foundation':'current'}">${l.scope}</span></div><div class="lesson-layout"><div><section class="panel"><h2>先理解原理</h2><p>${l.idea}</p><h3>解题顺序</h3><ol class="steps">${l.steps.map(s=>`<li><span>${s}</span></li>`).join('')}</ol></section><section class="panel" id="exercise"><h2>亲手解一道</h2><p class="mini">原创教学题 · 可忽略空格、标点和大小写</p>${l.tool==='mapping'?mappingBoard(l):`<div class="cipher-display">${l.cipher}</div>`}${l.key?`<p><strong>已知关键词：</strong><code>${l.key}</code></p>`:''}<label class="field-label" for="answer">${l.tool==='mapping'?'完整答案 · 上方字母格会自动填入':'你的明文或数字算式'}</label><textarea id="answer" class="answer-field" placeholder="在这里写出答案" spellcheck="false"></textarea><div class="control-row">${button('检查答案','check','primary')}${button('显示下一条提示','hint')}${button('显示讲解','reveal','secondary')}</div><div id="hints" class="hint-list" aria-live="polite"></div><div id="feedback" role="status" aria-live="polite"></div></section><div class="control-row"><button class="secondary" data-view="lessons">← 所有课程</button>${next?`<button class="secondary" data-lesson="${next.id}">下一课：${next.name} →</button>`:`<button class="primary" data-view="mock">进入定时模拟 →</button>`}</div></div><div><section class="panel" id="tool"><div class="tool-title"><h2>解码工作台</h2><span class="micro">可自由尝试</span></div>${toolMarkup(l)}</section><section class="panel"><h2>本课要记住</h2><p>${l.why}</p><p class="mini">掌握标记会在正确提交后自动保存到此浏览器。</p></section></div></div>`}
function mappingBoard(l){
  const source=l.id==='patristocrat'?l.cipher.match(/.{1,5}/g).join(' '):l.cipher;
  let position=0;
  const words=source.split(/\s+/).map(word=>`<span class="cipher-word">${[...word].map(c=>{if(!/[A-Z]/.test(c))return `<span class="cipher-punctuation">${c}</span>`;position++;return `<label class="cipher-cell"><input maxlength="1" inputmode="text" autocomplete="off" spellcheck="false" data-cipher-letter="${c}" aria-label="${c} 的明文字母，第 ${position} 位"><span aria-hidden="true">${c}</span></label>`}).join('')}</span>`).join('');
  return `<div class="cipher-board" aria-label="交互式替换密码题">${words}</div><p class="mini">在密文字母上方填明文字母；相同的密文字母会同步更新。</p>`;
}
function frequencyMarkup(l){const counts={};for(const c of l.cipher.replace(/[^A-Z]/g,''))counts[c]=(counts[c]||0)+1;return `<h3>字母频率</h3><div class="frequency-list" aria-label="密文字母出现次数">${Object.entries(counts).sort((a,b)=>b[1]-a[1]||a[0].localeCompare(b[0])).map(([c,n])=>`<span><strong>${c}</strong><small>${n}</small></span>`).join('')}</div>`}
const AZ='ABCDEFGHIJKLMNOPQRSTUVWXYZ';
function toolMarkup(l){if(l.tool==='caesar')return `<p>拖动移位量，观察实时解码结果。</p><div class="shift-control"><label for="shift">向左移 <strong id="shift-value">3</strong> 格</label><input id="shift" type="range" min="0" max="25" value="3"></div><div class="shift-preview" id="shift-preview"></div>`;
if(l.tool==='mapping')return `<p>可在题目字母格或下方对应表中填明文字母；相同密文字母会一起更新。</p><div class="mapping">${[...new Set(l.cipher.match(/[A-Z]/g))].sort().map(c=>`<label>${c}<input maxlength="1" aria-label="${c} 对应的明文字母" data-map="${c}" autocomplete="off"></label>`).join('')}</div><h3>当前预览</h3><div class="map-preview" id="map-preview"></div>${frequencyMarkup(l)}<button class="text-button" data-action="clear-map">重置字母</button>`;
if(l.tool==='bacon')return `<p>26 字母教学版：把 A 看作 0、B 看作 1，每五位一组。</p><div class="reference-grid">${AZ.split('').map((c,i)=>`<div>${c} ${i.toString(2).padStart(5,'0').replace(/0/g,'A').replace(/1/g,'B')}</div>`).join('')}</div>`;
if(l.tool==='morse')return `<p>点划先连成流，x 表示字母边界；每三个符号对应一个密文字母。</p><div class="reference-grid">${AZ.split('').map((c,i)=>`<div>${c} ${triplets()[i]}</div>`).join('')}</div><h3>常见摩斯码</h3><p class="cipher-display" style="font-size:14px">C -.-.　O ---　D -..　E .　T -　A .-</p>`;
if(l.tool==='porta')return `<p>关键词成对选行；下表给出相关行中 A–M 的对应密文字母。反向解密时，从表中找到密文字母所在列。</p><div style="overflow-x:auto"><table class="small-table porta-table"><tr><th>关键词行</th>${'ABCDEFGHIJKLM'.split('').map(c=>`<th>${c}</th>`).join('')}</tr>${[['C/D',1],['O/P',7],['E/F',2]].map(([name,k])=>`<tr><th>${name}</th>${'ABCDEFGHIJKLM'.split('').map((_,i)=>`<td>${AZ[13+(i+k)%13]}</td>`).join('')}</tr>`).join('')}</table></div>`;
if(l.tool==='homophonic')return `<p>不同符号可对应同一个字母。</p><table class="small-table"><tr><th>密文符号</th><th>41</th><th>07</th><th>19</th><th>74</th></tr><tr><th>已知字母</th><td>M</td><td>E</td><td>E</td><td>T</td></tr></table><p class="mini">正式题不会像本入门题一样把完整对应表全部给出。</p>`;
if(l.tool==='polybius'||l.tool==='checkerboard')return `<p>${l.tool==='polybius'?'入门方阵：I/J 共格，行号和列号组成两位数。':'入门方阵：行标签 C O D E S，列标签 T R A I N。'}</p><table class="small-table"><tr><th></th>${(l.tool==='polybius'?'12345':'TRAIN').split('').map(x=>`<th>${x}</th>`).join('')}</tr>${['ABCDE','FGHIK','LMNOP','QRSTU','VWXYZ'].map((row,i)=>`<tr><th>${l.tool==='polybius'?i+1:'CODES'[i]}</th>${row.split('').map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</table>`;
if(l.tool==='cryptarithm')return `<p>从右向左逐列写进位。两个四位数的和有五位，先想最高位的 M 可能是多少。</p><div class="cipher-display" style="font-size:18px;text-align:right">&nbsp; S E N D<br>+ M O R E<br>─────────<br>M O N E Y</div><p class="mini">同一字母同一数字；不同字母不可共用数字；S 与 M 不能为零。</p>`;
if(l.tool==='columnar')return `<p>原文填满 5 列 2 行，再按关键词字母顺序读列。</p><table class="small-table"><tr>${'ZEBRA'.split('').map(c=>`<th>${c}</th>`).join('')}</tr><tr>${'MEETA'.split('').map(c=>`<td>${c}</td>`).join('')}</tr><tr>${'TNOON'.split('').map(c=>`<td>${c}</td>`).join('')}</tr></table><p class="mini">读列次序：A → B → E → R → Z。</p>`;return ''}
function triplets(){const out=[];for(const a of '.-x')for(const b of '.-x')for(const c of '.-x')if(a+b+c!=='xxx')out.push(a+b+c);return out}
function activateTool(l){
  if(l.tool==='caesar'){const range=document.getElementById('shift');const update=()=>{document.getElementById('shift-value').textContent=range.value;document.getElementById('shift-preview').textContent=l.cipher.replace(/[A-Z]/g,c=>AZ[(AZ.indexOf(c)-Number(range.value)+26)%26])};range.addEventListener('input',update);update()}
  if(l.tool==='mapping'){
    let map={...(progress.maps?.[l.id]||{})};
    const fields=[...document.querySelectorAll('[data-map],[data-cipher-letter]')];
    const preview=document.getElementById('map-preview');
    const answer=document.getElementById('answer');
    const paint=()=>{for(const field of fields)field.value=map[field.dataset.map||field.dataset.cipherLetter]||'';const decoded=l.cipher.replace(/[A-Z]/g,c=>map[c]||'·');preview.textContent=decoded;if(Object.keys(map).length)answer.value=decoded};
    for(const field of fields)field.addEventListener('input',()=>{const cipher=field.dataset.map||field.dataset.cipherLetter;const plain=field.value.toUpperCase().replace(/[^A-Z]/g,'').slice(0,1);if(plain){for(const [other,value] of Object.entries(map))if(other!==cipher&&value===plain)delete map[other];map[cipher]=plain}else delete map[cipher];progress.maps||={};progress.maps[l.id]=map;saveProgress();paint()});
    paint();
  }
}
function handleCheck(){const l=findLesson(activeLesson);const value=document.getElementById('answer').value;const box=document.getElementById('feedback');progress.attempts=(progress.attempts||0)+1;if(norm(value)===norm(l.answer)){progress.done[l.id]=true;box.className='feedback good';box.textContent='正确！'+l.why}else{box.className='feedback bad';box.textContent=value.trim()?'还没完全正确。可以检查字母顺序、进位或查看下一条提示。':'先写下你的答案，再点击检查。'}saveProgress();renderNav()}
function showHint(){const l=findLesson(activeLesson);const n=Math.min((hintCount[l.id]||0)+1,l.hints.length);hintCount[l.id]=n;document.getElementById('hints').innerHTML=l.hints.slice(0,n).map((h,i)=>`<div class="hint"><strong>提示 ${i+1}：</strong>${h}</div>`).join('')}
function reveal(){const l=findLesson(activeLesson),box=document.getElementById('feedback');box.className='feedback';box.textContent=`参考答案：${l.answer}。${l.why}`}
const MOCK_IDS=['aristocrat','baconian','porta','nihilist','columnar'];
function ensureMock(){if(!mock)mock={started:false,finished:false,remaining:15*60,answers:{},result:null}}
function mockPage(){ensureMock();if(mock.finished)return mockResults();return `<div class="page-top"><div><h1>定时模拟</h1><p>5 道原创短题，覆盖不同密码类型。15 分钟计时，提交后一次判分并显示讲解。</p></div><span class="status current">2027 C 组题型 · 教学难度</span></div>${!mock.started?`<div class="panel"><h2>准备好了就开始</h2><p>这是一组教学短题，用来练节奏和跨题型切换；不模拟正式试卷的题量、配分或难度。</p><button class="primary" data-action="start-mock">开始 15 分钟</button></div>`:`<div class="mock-layout"><div>${MOCK_IDS.map((id,i)=>{const l=findLesson(id);return `<section class="panel mock-question"><h3>${i+1}. ${l.name}</h3><p class="mini">${l.idea}${l.key?` · 关键词 ${l.key}`:''}</p><div class="cipher-display">${l.cipher}</div><label class="field-label" for="mock-${id}">明文</label><textarea class="answer-field" id="mock-${id}" data-mock-answer="${id}" spellcheck="false" placeholder="写下答案">${mock.answers[id]||''}</textarea></section>`}).join('')}</div><aside class="mock-side"><div class="panel"><h2>剩余时间</h2><div class="timer" id="timer">15:00</div><p class="mini">时间到会自动交卷。答题会暂存在当前页面。</p><button class="primary" data-action="submit-mock">提交并判分</button></div></aside></div>`}`}
function renderMockTimer(){if(!mock?.started||mock.finished)return;const el=document.getElementById('timer');if(!el)return;const m=Math.floor(mock.remaining/60),s=mock.remaining%60;el.textContent=`${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`;el.classList.toggle('urgent',mock.remaining<=60)}
function startMock(){mock={started:true,finished:false,remaining:15*60,answers:{},result:null};clearInterval(tick);render();tick=setInterval(()=>{if(!mock||mock.finished){clearInterval(tick);return}mock.remaining--;renderMockTimer();if(mock.remaining<=0)finishMock()},1000)}
function finishMock(){if(!mock||mock.finished)return;clearInterval(tick);document.querySelectorAll('[data-mock-answer]').forEach(el=>mock.answers[el.dataset.mockAnswer]=el.value);const score=MOCK_IDS.filter(id=>norm(mock.answers[id])===norm(findLesson(id).answer)).length;mock.result=score;mock.finished=true;progress.bestMock=Math.max(progress.bestMock||0,score);progress.attempts=(progress.attempts||0)+MOCK_IDS.length;saveProgress();render()}
function mockResults(){return `<div class="page-top"><div><h1>模拟完成：${mock.result} / 5</h1><p>逐题看解析，找出下一步该复习的密码类型。</p></div><button class="top-action" data-action="reset-mock">再练一次</button></div><div class="stats"><div class="stat"><strong>${mock.result} / 5</strong><span>本次正确</span></div><div class="stat"><strong>${progress.bestMock||0} / 5</strong><span>最佳成绩</span></div><div class="stat"><strong>${Math.floor((15*60-mock.remaining)/60)} 分 ${String((15*60-mock.remaining)%60).padStart(2,'0')} 秒</strong><span>用时</span></div></div>${MOCK_IDS.map((id,i)=>{const l=findLesson(id),ok=norm(mock.answers[id])===norm(l.answer);return `<section class="panel mock-result"><h2>${i+1}. ${l.name} <span class="status ${ok?'done':'foundation'}">${ok?'正确':'待复习'}</span></h2><p>你的答案：${mock.answers[id]?.trim()||'未作答'}</p><div class="mock-answer"><strong>参考答案：</strong>${l.answer}<br>${l.why}</div><button class="text-button" data-lesson="${id}">复习这节课 →</button></section>`}).join('')}`}
function resources(){return `<div class="page-top"><div><h1>视频与规则</h1><p>先从官方入口获取 2027 Division C 手册；下方视频和工具供课外学习，不替代规则。</p></div></div><div class="notice"><p>截至 2026 年 11 月 2 日，官方 2027 规则页通过表单提供 Division C PDF。本网站无法直接读取表单后的手册全文；题型归类据官方 Codebusters 活动页链接的 Toebes 2026–27 汇总整理。请赛前再次核对手册、<a href="https://www.soinc.org/events/submit-question-and-rule-clarifications" target="_blank" rel="noopener">澄清与修订</a>及本州赛事要求。</p></div>${teacherResources()}<div class="section-head"><h2>正式范围怎么读</h2></div><div class="panel"><div class="two-col"><div><h3>本站作为 2027 C 组题型教授</h3><p>Aristocrat、Patristocrat、Xenocrypt、Baconian、Fractionated Morse、Porta、Homophonic、Nihilist Substitution、Checkerboard、Cryptarithm（十进制）、Complete Columnar。</p></div><div><h3>基础知识与名称区分</h3><p>Caesar 作为入门练习，不标为 2027 C 组正式题型；普通 Morse 是 Fractionated Morse 的前置知识。不同锦标赛级别的出题方式可能不同，本站短题均为教学简化题。</p></div></div></div><div class="section-head"><h2>核实过的资源入口</h2></div><div class="resource-list"><article class="resource"><h3>2027 官方 Division C 规则手册</h3><p>Science Olympiad 官方规则页；点击 Division C，填写表单获取 PDF。</p><a href="https://www.soinc.org/rules-2027" target="_blank" rel="noopener">打开官方规则页 ↗</a></article><article class="resource"><h3>Codebusters 官方活动页</h3><p>官方明确说明：活动页资料不扩展规则，现行手册优先。页面也链接旧赛季视频及练习。</p><a href="https://www.soinc.org/codebusters-c" target="_blank" rel="noopener">打开官方活动页 ↗</a></article><article class="resource"><h3>2026–27 题型汇总</h3><p>Toebes Codebusters 整理的各组别与赛事级别题型表，列有相应规则条款；属于辅助解读。</p><a href="https://ncc.toebes.com/codebusters/Rule-Summary-2027.html" target="_blank" rel="noopener">查看题型汇总 ↗</a></article><article class="resource"><h3>Codebusters 学习视频频道</h3><p>Toebes Codebusters 工具站链接的 @Codebusters-sciol 频道，提供各密码工具短视频。</p><a href="https://www.youtube.com/@Codebusters-sciol" target="_blank" rel="noopener">打开视频频道 ↗</a></article><article class="resource"><h3>2026 Codebusters 备赛讲座</h3><p>Science Olympiad 官方活动页列出的 “Advice & Preparation Ideas” 视频。讲座为旧赛季内容，题型范围请按 2027 手册核对。</p><a href="https://www.youtube.com/watch?v=rF8qobfKfdw" target="_blank" rel="noopener">观看讲座 ↗</a></article><article class="resource"><h3>Cryptarithm 生成与练习视频</h3><p>Science Olympiad 官方活动页收录的教学视频，侧重如何生成题目。</p><a href="https://www.youtube.com/watch?v=rH18JSQiS6Q" target="_blank" rel="noopener">观看视频 ↗</a></article><article class="resource"><h3>Toebes 测验生成器教程</h3><p>Toebes 网站列出的工具入门视频，适合教练与学生创建额外练习。</p><a href="https://www.youtube.com/watch?v=miV-4S38tX8" target="_blank" rel="noopener">观看教程 ↗</a></article></div>`}
document.addEventListener('click',e=>{const lesson=e.target.closest('[data-lesson]');if(lesson){navigate('lesson',lesson.dataset.lesson);return}const v=e.target.closest('[data-view]');if(v){navigate(v.dataset.view);return}const a=e.target.closest('[data-action]');if(!a)return;switch(a.dataset.action){case'check':handleCheck();break;case'hint':showHint();break;case'reveal':reveal();break;case'clear-map':progress.maps||={};progress.maps[activeLesson]={};saveProgress();document.querySelectorAll('[data-map],[data-cipher-letter]').forEach(x=>x.value='');document.getElementById('map-preview').textContent=findLesson(activeLesson).cipher.replace(/[A-Z]/g,'·');document.getElementById('answer').value='';break;case'start-mock':startMock();break;case'submit-mock':finishMock();break;case'reset-mock':mock=null;render();break}});
document.addEventListener('input',e=>{if(e.target.matches('[data-mock-answer]')&&mock)mock.answers[e.target.dataset.mockAnswer]=e.target.value});
document.getElementById('menu-toggle').addEventListener('click',()=>{const side=document.getElementById('sidebar');const open=side.classList.toggle('open');document.getElementById('menu-toggle').setAttribute('aria-expanded',String(open))});document.getElementById('mobile-mock').addEventListener('click',()=>navigate('mock'));
function fromHash(){const h=location.hash.replace(/^#/,'');if(h.startsWith('lesson/')){const id=h.split('/')[1];if(findLesson(id)){view='lesson';activeLesson=id}}else if(['home','lessons','mock','resources'].includes(h))view=h;else view='home';render()}
window.addEventListener('hashchange',fromHash);fromHash();
function teacherResources(){return `<div class="section-head"><h2>老师指定的四个资源</h2><p>按用途挑选，建议先练再看解法。</p></div><div class="resource-list"><article class="resource"><h3>Puzzle Baron · 在线 Cryptograms</h3><p>直接在网页上练英文单字母替换，适合熟悉词形、字母频率和填表。它主要练 Aristocrat 类技能，并不覆盖所有 Codebusters 题型。</p><a href="https://cryptograms.puzzlebaron.com/play.php" target="_blank" rel="noopener">开始练习 ↗</a></article><article class="resource"><h3>Toebes · Codebusters 工具与练习</h3><p>可创建单题或练习卷，另有解题指南、2026–27 题型汇总和教学视频。练正式赛题前先选择 Division C 与对应赛事级别。</p><a href="https://toebes.com/codebusters/index.html" target="_blank" rel="noopener">打开工具站 ↗</a></article><article class="resource"><h3>Scio.ly · 2027 Codebusters Study Guide</h3><p>英文分题型学习指南，含 2027 范围、策略和各密码的专题链接。它是社区学习资料，规则仍以官方手册为准。</p><a href="https://www.scio.ly/guides/codebusters" target="_blank" rel="noopener">阅读学习指南 ↗</a></article><article class="resource"><h3>Toebes · Codebusters Overview PDF</h3><p>John Toebes 的长篇指南，首页标注更新至 2026–27 赛季；包含分题型方法和历史内容。阅读旧题型章节时，请对照 PDF 中的“当前使用”说明与官方规则。</p><a href="https://toebes.com/codebusters/Samples/CodeBusters_Overview.pdf" target="_blank" rel="noopener">打开 120 页 PDF ↗</a></article></div>`}

function syncLanguageLinks(){for(const id of ['lang-switch','lang-switch-mobile']){const link=document.getElementById(id);if(link)link.href=`index.html${location.hash}`}}
